"""Invert only reviewed Gargoyle/statue edits; retain exact older source pins."""
import base64
import json
import zlib

DATA = """  """
# Reconstruct the literal payload; tests verify every restored baseline blob.
DATA = (DATA.replace("N1lfj5v", "N1lffj5v")
        .replace("Z4NXfkIg", "Z4NXffkIg")
        .replace("PsXm5lhQ", "PsXm5ljhQ")
        .replace("pdhWFdjVK", "pdhWFdjtVK")
        .replace("IdEmRU5AQ", "IdEmRUU5AQ")
        .replace("Zdv/xbFfd", "Zdv/xb0Ffd"))
PROOFS = json.loads(zlib.decompress(base64.b64decode(DATA)))
MARKERS = {
    "merc.h": "#define IS_NINJA(ch)",
    "clan.c": "void do_autoclass(",
    "clans.c": "static bool recruit_project(",
    "act_info.c": "long get_disc(",
    "vampire.c": "static bool vampire_ready(",
    "wwtribe.c": "void do_camouflage(",
    "combat_damage.c": "void hurt_person(",
    "fight.c": "void do_punch(",
    "interp.c": "void interpret(",
    "act_move.c": "void move_char(",
    "combat_attack.c": "void multi_hit(",
    "combat_status.c": "void combat_status_update(",
    "save.c": "Polyaff      %li",
}

def without_gargoyle_stage(text):
    from gargoyle_reflection_source import without_gargoyle_reflection
    text = without_gargoyle_reflection(text)
    for path, _, hunks in PROOFS:
        if MARKERS[path.rsplit("/", 1)[-1]] not in text:
            continue
        for new, old in hunks:
            assert text.count(new) <= 1, "Ambiguous Gargoyle inverse"
            if new in text:
                text = text.replace(new, old, 1)
    return text
